mapper.sql:
WHERE d.workspace_id = #{q.workspaceId}
 AND d.req_id = #{q.reqId} 
 AND d.status = #{q.status} 
 AND  = #{q.deliveryStage} 
 AND d.version_id IS NULL 
 AND d.version_id = #{q.versionId} 
 AND d.close_reason = #{q.closeReason} 
 AND d.close_stage = #{q.closeStage} 
 AND d.priority IN ('P0', 'P1') 

  AND d.expect_date IS NOT NULL AND d.expect_date <= DATE_ADD(CURRENT_DATE, INTERVAL 30 DAY)

 AND () 

  AND (d.title LIKE CONCAT('%', #{q.q}, '%')
       OR d.description LIKE CONCAT('%', #{q.q}, '%')
       OR d.source LIKE CONCAT('%', #{q.q}, '%')
       OR EXISTS (SELECT 1 FROM category cg
                  WHERE cg.id = d.category_id AND cg.workspace_id = d.workspace_id
                    AND cg.name LIKE CONCAT('%', #{q.q}, '%')))


  AND d.priority IN
  #{p}


  AND d.item_kind IN
  #{k}


  AND d.category_id IN
  #{c}


  AND d.req_id IN
  #{r}


  AND NOT EXISTS (SELECT 1 FROM project_member pm
                  WHERE pm.workspace_id = d.workspace_id
                    AND pm.project_id = d.req_id
                    AND pm.user_id = #{q.viewerId}
                    AND pm.access = 'none')

